import React, { useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom';
import Sidenav from '../component/Sidenav';
import Utopnav from '../component/Utopnav';

const ViewComQuery = () => {

    const {id}=useParams();
   const [penquery, setPenQuery]=useState([]);
   var [count, setCount]=useState(1);
   const getpenquery=async()=>{
    const response=await fetch(`http://localhost:8000/getcomquery/${id}`);
    const data= await response.json();
    if (data.msg==="Success") {
        setPenQuery(data.result);
        console.log(penquery);
    } 
   
   } 

   const process = async (id)=>{
    const status = {'status':"pen"}
    const response = await fetch(`http://localhost:8000/status/${id}`,{
        method:'PATCH',
        headers:{
            'Content-Type':'application/json',
        },
        body:JSON.stringify(status),
    });
    const data = await response.json();
    if(data.msg=="Success"){
        alert("Query Raise Again");
        getpenquery();
    }
    else{
        alert("Error");
    }

    
   }
   useEffect(()=>{
    getpenquery();
   },[]);

  return (
    <>
    <div className='row vh-7' >
      <div className='col-sm-12  bg-dark text-light'>
      <Utopnav/>
      </div>
    </div>
    <div className='row vh-93'  >
      <div className='col-2 h-100 scroll bg-danger'>
        <Sidenav/>
      </div>
      <div className='col-10 h-100 scroll bg-success'>
        <div className='row h-100'>
        <div className='col-md-6 table-responsive mx-auto p-2 my-auto rounded-4 shadow-lg bg-light'>
            <table className='table table-light'>
                <thead>
                    <tr>
                        <th>Sr. No.</th>
                        <th>Department</th>
                        <th>Subject</th>
                        <th>Query</th>
                        <th colSpan={2}>Action</th>
                    </tr>
                </thead>
                <tbody>
                {penquery.map((e)=>(
                    <tr>
                        <td>{count++}</td>
                        <td>{e.department}</td>
                        <td>{e.subject}</td>
                        <td>{e.description}</td>
                        <td><Link to={'/'} className='btn btn-danger'>Delete</Link></td>
                        <td><button onClick={()=>{process(e._id)}} className='btn btn-warning'>Raise Again</button></td>
                    </tr>
                ))}
                </tbody>
            </table>
        </div>
        
        </div>
      </div>
    </div>

    </>
  )
}
export default ViewComQuery
